"""Stage 7 Validate: suggestions_raw.json, claims.json, the corpus emails, results.json -> suggestions_checked.json.

Pure code; no generative model. See SPEC.md: Validation in stage 7. Rules run in this
fixed order, and the first rule that rejects ends the check:

1. Unknown item (reject): a claim ID that is not one of the email's claims; a section
   quoting another email; a pillar outside the candidate set recomputed from the claims'
   tickers plus the pillars links.json ties to them; a new thesis on a ticker outside
   the claims' tickers; a new pillar naming a driver that is not its own company's.
2. Quote mismatch (reject): a section not found verbatim in the email body (`quote_in`).
3. Duplicate thesis (reject): a new-thesis statement whose cosine with any existing
   pillar statement reaches `thresholds.NEW_THESIS_DUPLICATE` (stage 2 embedding model).
4. Monitor only: every linked email is labeled monitor. Strength becomes 1; a new-thesis
   candidate is rejected.
5. Out of bounds (keep, drop the figure): a stated value outside the driver's bounds, or
   a driver the pillar is not linked to.
6. Figure not stated (keep, drop the figure): no claim of the suggestion states the figure
   for exactly the company's modeled fiscal year with the number itself in the claim's
   quote. Value and period are model output; the quote is checked text, so a number the
   email never states cannot reach the analyst.
7. Second look (keep, mark): no linked email is labeled thesis_relevant or monitor.

A rejected suggestion keeps everything it had, with status "rejected" and a one-line
`reject_reason`.
"""

import math
import re
from collections import defaultdict
from collections.abc import Collection
from pathlib import Path

import numpy as np

from triage_app import thresholds
from triage_app import config
from triage_app.embed import Vector
from triage_app.pipeline.context import RunContext
from triage_app.pipeline.io import quote_in, read_list, write_list
from triage_app.schema import (
    Claim,
    CompanyModel,
    Email,
    EmailResult,
    ExistingThesis,
    LinkedAssumption,
    NewThesis,
    Pillar,
    Suggestion,
)
from triage_app.state.fold import Seed, load_seed

STAGE = "validate"
SIGNAL_LABELS = ("thesis_relevant", "monitor")


class Rejected(Exception):
    """Raised by a rule that rejects; the message is the one-line reason."""


class ValidationInputs:
    """Everything the rules look up: the set's claims, email bodies and results, and the book."""

    def __init__(self, claims: list[Claim], emails: list[Email], results: list[EmailResult],
                 seed: Seed) -> None:
        self.claims: dict[str, Claim] = {c.id: c for c in claims}
        self.bodies: dict[str, str] = {e.email_id: e.body for e in emails}
        self.results: dict[str, EmailResult] = {r.email_id: r for r in results}
        self.models: dict[str, CompanyModel] = {m.ticker: m for m in seed.models}
        self.pillars: dict[str, Pillar] = {p.id: p for t in seed.theses for p in t.pillars}
        self.links: dict[str, list[str]] = defaultdict(list)
        for link in seed.links:
            self.links[link.from_ticker].extend(link.to_pillar_ids)
        self._pillar_vectors: Vector | None = None

    def candidates(self, tickers: Collection[str]) -> set[str]:
        """Every pillar of each ticker, plus the pillars the links tie to those tickers."""
        found = {pid for pid in self.pillars if pid.split(".")[0] in tickers}
        for ticker in tickers:
            found.update(self.links.get(ticker, []))
        return found

    def pillar_vectors(self, ctx: RunContext) -> tuple[list[str], Vector]:
        ids = list(self.pillars)
        if self._pillar_vectors is None:
            self._pillar_vectors = ctx.embedder.embed([self.pillars[i].statement for i in ids])
        return ids, self._pillar_vectors


def email_of(suggestion_id: str) -> str:
    """The email a raw suggestion came from: `<email_id>.s<n>`."""
    return suggestion_id.rsplit(".s", 1)[0]


def linked_emails(suggestion: Suggestion) -> list[str]:
    """Every email a suggestion links to, by its sections and claims, in first-seen order."""
    ids = [s.email_id for s in suggestion.sections] + [c.rsplit(".c", 1)[0] for c in suggestion.claim_ids]
    return list(dict.fromkeys(ids))


def needs_second_look(suggestion: Suggestion, results: dict[str, EmailResult]) -> bool:
    return not any(_label(results, e) in SIGNAL_LABELS for e in linked_emails(suggestion))


def _label(results: dict[str, EmailResult], email_id: str) -> str | None:
    result = results.get(email_id)
    return result.triage if result else None


def _check_unknown(suggestion: Suggestion, email_id: str, inputs: ValidationInputs) -> None:
    for cid in suggestion.claim_ids:
        claim = inputs.claims.get(cid)
        if claim is None or claim.email_id != email_id:
            raise Rejected(f"unknown item: {cid} is not a claim of {email_id}")
    for section in suggestion.sections:
        if section.email_id != email_id:
            raise Rejected(f"unknown item: section quotes {section.email_id}, not {email_id}")
    tickers = {t for cid in suggestion.claim_ids for t in inputs.claims[cid].tickers}
    body = suggestion.body
    if isinstance(body, ExistingThesis):
        if body.pillar_id not in inputs.candidates(tickers):
            raise Rejected(f"unknown item: pillar {body.pillar_id} is not a candidate for the claims' tickers")
    elif isinstance(body, NewThesis):
        if body.ticker not in tickers:
            raise Rejected(f"unknown item: new thesis on {body.ticker}, outside the claims' tickers")
        own = {d.id for d in inputs.models[body.ticker].drivers} if body.ticker in inputs.models else set()
        for driver_id in body.driver_ids:
            if driver_id not in own:
                raise Rejected(f"unknown item: driver {driver_id} is not a driver of {body.ticker}")
    else:
        raise Rejected(f"unknown item: stage 6 does not raise {body.kind}")


def _check_quotes(suggestion: Suggestion, inputs: ValidationInputs) -> None:
    for section in suggestion.sections:
        if not quote_in(section.quote, inputs.bodies.get(section.email_id, "")):
            raise Rejected(f"quote mismatch: section not found in {section.email_id}")


def _check_duplicate(body: NewThesis, inputs: ValidationInputs, ctx: RunContext) -> None:
    ids, vectors = inputs.pillar_vectors(ctx)
    if not ids:
        return
    sims = vectors @ ctx.embedder.embed([body.statement])[0]
    best = int(np.argmax(sims))
    if float(sims[best]) >= thresholds.NEW_THESIS_DUPLICATE:
        raise Rejected(f"duplicate thesis: statement matches {ids[best]} ({float(sims[best]):.2f})")


def _figure_in_bounds(a: LinkedAssumption, pillar: Pillar | None, model: CompanyModel | None) -> bool:
    if pillar is None or model is None or a.driver_id not in pillar.driver_ids:
        return False
    driver = next((d for d in model.drivers if d.id == a.driver_id), None)
    return driver is not None and driver.min <= a.stated_value <= driver.max


_NUMBER = re.compile(r"\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+(?:\.\d+)?")


def numbers_in(text: str) -> list[float]:
    """Every number written in the text ("4,500", "31.0%", "-2" all count; signs are ignored)."""
    return [float(n.replace(",", "")) for n in _NUMBER.findall(text)]


def _figure_stated(a: LinkedAssumption, claims: list[Claim], model: CompanyModel | None) -> bool:
    if model is None:
        return False
    return any(c.value is not None and math.isclose(c.value, a.stated_value) and c.period == model.fiscal_year
               and any(math.isclose(n, abs(a.stated_value)) for n in numbers_in(c.quote))
               for c in claims)


def check(suggestion: Suggestion, ctx: RunContext, inputs: ValidationInputs) -> Suggestion:
    """Apply rules 1 to 7 in order; raises Rejected at the first rule that rejects."""
    email_id = email_of(suggestion.id)
    _check_unknown(suggestion, email_id, inputs)
    _check_quotes(suggestion, inputs)
    body = suggestion.body
    if isinstance(body, NewThesis):
        _check_duplicate(body, inputs, ctx)
    monitor_only = all(_label(inputs.results, e) == "monitor" for e in linked_emails(suggestion))
    if isinstance(body, NewThesis):
        if monitor_only:
            raise Rejected("monitor only: a new thesis needs an email not labeled monitor")
    elif isinstance(body, ExistingThesis):
        pillar = inputs.pillars.get(body.pillar_id)
        model = inputs.models.get(body.pillar_id.split(".")[0])
        claims = [inputs.claims[c] for c in suggestion.claim_ids]
        kept = [a for a in body.assumptions
                if _figure_in_bounds(a, pillar, model) and _figure_stated(a, claims, model)]
        body = body.model_copy(update={"strength": 1 if monitor_only else body.strength, "assumptions": kept})
    checked = suggestion.model_copy(update={"body": body})
    return checked.model_copy(update={"second_look": needs_second_look(checked, inputs.results)})


def process(suggestion: Suggestion, ctx: RunContext, inputs: ValidationInputs) -> Suggestion:
    """Valid, adjusted (figure dropped, strength capped, second look), or rejected with a reason."""
    if suggestion.status != "open":
        return suggestion
    try:
        return check(suggestion, ctx, inputs)
    except Rejected as reason:
        return suggestion.model_copy(update={"status": "rejected", "reject_reason": str(reason)})


def run(in_dir: Path, out_dir: Path, ctx: RunContext, seed: Seed | None = None) -> None:
    raw = read_list(in_dir / "suggestions_raw.json", Suggestion)
    inputs = ValidationInputs(
        claims=read_list(in_dir / "claims.json", Claim),
        emails=ctx.emails,
        results=read_list(in_dir / "results.json", EmailResult),
        seed=seed or load_seed(),
    )
    by_email: dict[str, list[Suggestion]] = defaultdict(list)
    for s in raw:
        by_email[email_of(s.id)].append(s)
    checked: list[Suggestion] = []
    for email_id, suggestions in by_email.items():
        with ctx.recorder.stage(STAGE, email_id):
            checked.extend(process(s, ctx, inputs) for s in suggestions)
    write_list(out_dir / "suggestions_checked.json", checked)
"""Stage 8 Merge and rank: suggestions_checked.json -> suggestions.json.

Pure code. See SPEC.md: Merging in stage 8; Order and alerts (ordering only; alerts are
stage 9's). Only open suggestions are kept; rejected ones stay in suggestions_checked.json.

- Existing-thesis suggestions on the same pillar and stance merge into one, with ID
  `<pillar_id>.<stance>`: the highest strength (ties go to the email with the higher
  signal score, then the earlier suggestion), its rationale, `wrong_if_met` if any had it,
  assumptions pooled one per driver and stated value, and every claim and section kept.
  Opposite stances on one pillar stay two suggestions.
- New-thesis candidates for one company merge when a statement's cosine with a group's
  first statement reaches `thresholds.NEW_THESIS_MERGE`. The first candidate's statement,
  "wrong if" test and rationale are kept; drivers, claims and sections are pooled. IDs
  are `<ticker>.new<n>`, numbered per company in arrival order.
- Second look is recomputed from the merged emails.
- Order: existing pillars by position size, then strength, then the highest signal score
  among the linked emails; then new-thesis candidates by position size, then signal score.
"""

from collections import defaultdict
from pathlib import Path
from typing import Any

from triage_app import thresholds
from triage_app import config
from triage_app.pipeline.context import RunContext
from triage_app.pipeline.io import read_list, write_list
from triage_app.pipeline.validate import linked_emails, needs_second_look
from triage_app.schema import EmailResult, ExistingThesis, LinkedAssumption, LinkedSection, NewThesis, Suggestion
from triage_app.state.fold import Seed, load_seed

STAGE = "merge"


def _signal(s: Suggestion, results: dict[str, EmailResult]) -> float:
    return max((results[e].signal_score for e in linked_emails(s) if e in results), default=0.0)


def _pool(group: list[Suggestion]) -> dict[str, Any]:
    """Every claim and every distinct section of the group, in first-seen order."""
    sections: dict[tuple[str, str], LinkedSection] = {}
    for s in group:
        for sec in s.sections:
            sections.setdefault((sec.email_id, sec.quote), sec)
    return {
        "claim_ids": list(dict.fromkeys(c for s in group for c in s.claim_ids)),
        "sections": list(sections.values()),
    }


def merge_existing(group: list[Suggestion], results: dict[str, EmailResult]) -> Suggestion:
    """One suggestion for one pillar and stance."""
    bodies = [s.body for s in group if isinstance(s.body, ExistingThesis)]
    strongest = max(range(len(group)),
                    key=lambda i: (bodies[i].strength, _signal(group[i], results), -i))
    pooled: dict[tuple[str, float], LinkedAssumption] = {}
    for b in bodies:
        for a in b.assumptions:
            pooled.setdefault((a.driver_id, a.stated_value), a)
    body = bodies[strongest].model_copy(update={
        "wrong_if_met": any(b.wrong_if_met for b in bodies),
        "assumptions": list(pooled.values()),
    })
    lead = bodies[strongest]
    return group[strongest].model_copy(update={
        "id": f"{lead.pillar_id}.{lead.stance}", "body": body, **_pool(group),
    })


def merge_new(group: list[Suggestion], ticker: str, n: int) -> Suggestion:
    """One candidate from similar new-thesis candidates for one company; the first is kept."""
    bodies = [s.body for s in group if isinstance(s.body, NewThesis)]
    drivers = list(dict.fromkeys(d for b in bodies for d in b.driver_ids))
    return group[0].model_copy(update={
        "id": f"{ticker}.new{n}", "body": bodies[0].model_copy(update={"driver_ids": drivers}),
        **_pool(group),
    })


def group_new(candidates: list[Suggestion], ctx: RunContext) -> list[list[Suggestion]]:
    """Greedy grouping in arrival order against each group's first statement."""
    if not candidates:
        return []
    vectors = ctx.embedder.embed([s.body.statement for s in candidates if isinstance(s.body, NewThesis)])
    groups: list[list[int]] = []
    for i in range(len(candidates)):
        for g in groups:
            if float(vectors[g[0]] @ vectors[i]) >= thresholds.NEW_THESIS_MERGE:
                g.append(i)
                break
        else:
            groups.append([i])
    return [[candidates[i] for i in g] for g in groups]


def process(suggestions: list[Suggestion], ctx: RunContext, results: list[EmailResult],
            seed: Seed) -> list[Suggestion]:
    """One suggestion per pillar and stance, merged and ordered."""
    by_email = {r.email_id: r for r in results}
    size: dict[str, int] = {t.ticker: t.size_bps for t in seed.theses}
    existing: dict[tuple[str, str], list[Suggestion]] = defaultdict(list)
    new: dict[str, list[Suggestion]] = defaultdict(list)
    for s in suggestions:
        if s.status != "open":
            continue
        if isinstance(s.body, ExistingThesis):
            existing[(s.body.pillar_id, s.body.stance)].append(s)
        elif isinstance(s.body, NewThesis):
            new[s.body.ticker].append(s)

    merged_existing = [merge_existing(g, by_email) for g in existing.values()]
    merged_new = [merge_new(g, ticker, n)
                  for ticker, candidates in new.items()
                  for n, g in enumerate(group_new(candidates, ctx), start=1)]
    merged = [m.model_copy(update={"second_look": needs_second_look(m, by_email)})
              for m in merged_existing + merged_new]

    def ticker_of(s: Suggestion) -> str:
        b = s.body
        return b.pillar_id.split(".")[0] if isinstance(b, ExistingThesis) else b.ticker

    def strength(s: Suggestion) -> int:
        return s.body.strength if isinstance(s.body, ExistingThesis) else 0

    return sorted(merged, key=lambda s: (
        isinstance(s.body, NewThesis), -size.get(ticker_of(s), 0), -strength(s),
        -_signal(s, by_email), s.id,
    ))


def run(in_dir: Path, out_dir: Path, ctx: RunContext, seed: Seed | None = None) -> None:
    # Merging works across emails, so it is timed once for the set (by run.py), not per email.
    checked = read_list(in_dir / "suggestions_checked.json", Suggestion)
    results = read_list(in_dir / "results.json", EmailResult)
    write_list(out_dir / "suggestions.json", process(checked, ctx, results, seed or load_seed()))
"""Revenue, EPS and target price from a company's drivers. Pure functions.

- Revenue is the sum of each line's base revenue times one plus its growth.
- Operating income is revenue times operating margin.
- EPS is operating income, less tax, divided by diluted shares.
- Target price is EPS times the target multiple.

`pct` drivers are in percentage points (12.5 means 12.5%); the tax rate is a fraction.
Capex does not feed EPS.
"""

from collections.abc import Mapping
from typing import Literal

from pydantic import BaseModel

from triage_app.schema import CompanyModel


class Projection(BaseModel):
    revenue_usd_bn: float
    operating_income_usd_bn: float
    eps: float
    target_price: float


def driver_values(model: CompanyModel, basis: Literal["analyst", "consensus"]) -> dict[str, float]:
    return {d.id: (d.analyst if basis == "analyst" else d.consensus) for d in model.drivers}


def project(model: CompanyModel, values: Mapping[str, float]) -> Projection:
    revenue = sum(line.base_revenue_usd_bn * (1 + values[line.driver_id] / 100) for line in model.revenue_lines)
    operating_income = revenue * values[f"{model.ticker}.operating_margin"] / 100
    eps = operating_income * (1 - model.tax_rate) / model.diluted_shares_bn
    return Projection(
        revenue_usd_bn=revenue,
        operating_income_usd_bn=operating_income,
        eps=eps,
        target_price=eps * model.target_multiple,
    )


def compute(model: CompanyModel) -> dict[str, Projection]:
    """Projections on the analyst's values and on consensus."""
    return {
        "analyst": project(model, driver_values(model, "analyst")),
        "consensus": project(model, driver_values(model, "consensus")),
    }


OUTPUT_METRICS = ("revenue", "operating_income", "eps", "target_price")
_OUTPUT_FIELD = {"revenue": "revenue_usd_bn", "operating_income": "operating_income_usd_bn",
                 "eps": "eps", "target_price": "target_price"}


def metric_value(model: CompanyModel, metric: str, basis: Literal["analyst", "consensus"]) -> float | None:
    """A projection metric's value on the analyst's or consensus drivers.

    `metric` is one of the company's driver IDs (its value), or an output metric:
    revenue and operating income in USD billions, EPS and target price in USD.
    None when the metric is neither.
    """
    values = driver_values(model, basis)
    if metric in values:
        return values[metric]
    if metric in _OUTPUT_FIELD:
        return float(getattr(project(model, values), _OUTPUT_FIELD[metric]))
    return None

"""Pure functions for every measure in SPEC.md, "Evaluation and guardrails".

Each measure takes pipeline output and corpus labels keyed by email ID and returns a
`Score`: the value (None when undefined, e.g. no positives) and the misses behind it.

A quarantined email counts as a miss on every label measure: its label is "quarantined",
it does not pass the gate, and it predicts no ticker, topic or attention flag. Labels are
the universe: an email with a label but no result is treated as quarantined.

Only evals and the corpus loader read EmailLabel.
"""

from collections.abc import Callable, Iterable, Mapping
from dataclasses import dataclass, field

from triage_app import config
from triage_app.config import TICKERS, TOPICS
from triage_app.pipeline.io import quote_in
from triage_app.schema import (
    AttentionNote,
    EmailLabel,
    EmailResult,
    LinkedSection,
    Miss,
    RedundancyRecord,
    Suggestion,
    TriageRecord,
)

QUARANTINED = "quarantined"
SIGNAL_CLASS = {
    "thesis_relevant": "signal", "monitor": "signal", "redundant": "redundant",
    "low_value": "noise", "irrelevant": "noise",
}
NOISE_LABELS = frozenset({"redundant", "low_value", "irrelevant"})

# The measures reported per split by the criteria check (all label measures with a value).
LABEL_MEASURES = ("gate_recall", "monitor_gate_recall", "signal_accuracy", "triage_accuracy",
                  "ticker_f1", "topic_f1", "human_attention_precision", "human_attention_recall")

Results = Mapping[str, EmailResult]
Labels = Mapping[str, EmailLabel]


@dataclass
class Score:
    value: float | None
    misses: list[Miss] = field(default_factory=list)


def _ratio(num: int, den: int) -> float | None:
    return round(num / den, 4) if den else None


def _get(results: Results, email_id: str) -> EmailResult | None:
    """The result for an email, or None when it is quarantined or missing."""
    r = results.get(email_id)
    return None if r is None or r.gate == "quarantine" else r


def pipeline_label(results: Results, email_id: str) -> str:
    r = _get(results, email_id)
    return QUARANTINED if r is None or r.triage is None else r.triage


def _gate(results: Results, email_id: str) -> str:
    r = results.get(email_id)
    return "missing" if r is None else r.gate


def _joined(items: Iterable[str], order: tuple[str, ...]) -> str:
    s = set(items)
    return ",".join(x for x in order if x in s) or "none"


# ---- Gate ----

def _gate_recall_for(label: str, measure: str, results: Results, labels: Labels) -> Score:
    ids = [i for i, lab in labels.items() if lab.triage == label]
    misses = [Miss(email_id=i, measure=measure, expected="pass", got=_gate(results, i))
              for i in ids if _gate(results, i) != "pass"]
    return Score(_ratio(len(ids) - len(misses), len(ids)), misses)


def gate_recall(results: Results, labels: Labels) -> Score:
    """Share of corpus thesis_relevant emails that pass the gate."""
    return _gate_recall_for("thesis_relevant", "gate_recall", results, labels)


def monitor_gate_recall(results: Results, labels: Labels) -> Score:
    """Share of corpus monitor emails that pass the gate."""
    return _gate_recall_for("monitor", "monitor_gate_recall", results, labels)


def gate_reduction(results: Results, labels: Labels) -> Score:
    """Share of emails stopped (or quarantined) before the analysis model."""
    stopped = sum(1 for i in labels if _gate(results, i) != "pass")
    return Score(_ratio(stopped, len(labels)))


# ---- Labels ----

def signal_accuracy(results: Results, labels: Labels) -> Score:
    """Label correct on three classes: signal, redundant, noise."""
    misses = []
    for i, lab in labels.items():
        expected = SIGNAL_CLASS[lab.triage]
        got = SIGNAL_CLASS.get(pipeline_label(results, i), QUARANTINED)
        if got != expected:
            misses.append(Miss(email_id=i, measure="signal_accuracy", expected=expected, got=got))
    return Score(_ratio(len(labels) - len(misses), len(labels)), misses)


def triage_accuracy(results: Results, labels: Labels) -> Score:
    """Label equals the corpus label exactly, on all five."""
    misses = [Miss(email_id=i, measure="triage_accuracy", expected=lab.triage, got=pipeline_label(results, i))
              for i, lab in labels.items() if pipeline_label(results, i) != lab.triage]
    return Score(_ratio(len(labels) - len(misses), len(labels)), misses)


def confusion(results: Results, labels: Labels) -> dict[str, dict[str, int]]:
    """Corpus label, then pipeline label ("quarantined" when quarantined)."""
    table: dict[str, dict[str, int]] = {}
    for i, lab in labels.items():
        row = table.setdefault(lab.triage, {})
        got = pipeline_label(results, i)
        row[got] = row.get(got, 0) + 1
    return table


def _micro_f1(measure: str, order: tuple[str, ...], labels: Labels,
              predicted: Callable[[str], set[str]], expected: Callable[[EmailLabel], set[str]]) -> Score:
    tp = fp = fn = 0
    misses = []
    for i, lab in labels.items():
        want, got = expected(lab), predicted(i)
        tp += len(want & got)
        fp += len(got - want)
        fn += len(want - got)
        if want != got:
            misses.append(Miss(email_id=i, measure=measure, expected=_joined(want, order), got=_joined(got, order)))
    return Score(_ratio(2 * tp, 2 * tp + fp + fn), misses)


def ticker_f1(results: Results, labels: Labels) -> Score:
    """Micro-averaged F1 on affected_tickers."""
    def predicted(i: str) -> set[str]:
        r = _get(results, i)
        return set(r.affected_tickers) if r else set()
    return _micro_f1("ticker_f1", TICKERS, labels, predicted, lambda lab: set(lab.affected_tickers))


def topic_f1(results: Results, labels: Labels) -> Score:
    """Micro-averaged F1 on macro, sector, government and other."""
    def predicted(i: str) -> set[str]:
        r = _get(results, i)
        return set(r.additional_labels) if r else set()
    return _micro_f1("topic_f1", TOPICS, labels, predicted, lambda lab: set(lab.additional_labels))


def _attention(results: Results, email_id: str) -> bool:
    r = _get(results, email_id)
    return bool(r and r.human_attention)


def human_attention_precision(results: Results, labels: Labels) -> Score:
    flagged = [i for i in labels if _attention(results, i)]
    misses = [Miss(email_id=i, measure="human_attention_precision", expected="false", got="true")
              for i in flagged if not labels[i].human_attention]
    return Score(_ratio(len(flagged) - len(misses), len(flagged)), misses)


def human_attention_recall(results: Results, labels: Labels) -> Score:
    wanted = [i for i, lab in labels.items() if lab.human_attention]
    misses = [Miss(email_id=i, measure="human_attention_recall", expected="true", got="false")
              for i in wanted if not _attention(results, i)]
    return Score(_ratio(len(wanted) - len(misses), len(wanted)), misses)


# ---- Repeats ----

def repeat_flagged(redundancy: Iterable[RedundancyRecord]) -> Score:
    """Count of emails the redundancy check flags; an email absent from redundancy.json is not flagged."""
    return Score(float(sum(1 for r in redundancy if r.flagged)))


def repeat_precision(redundancy: Iterable[RedundancyRecord], labels: Labels) -> Score:
    """Share of flagged emails the corpus labels redundant."""
    flagged = [r for r in redundancy if r.flagged and r.email_id in labels]
    misses = [Miss(email_id=r.email_id, measure="repeat_precision", expected=labels[r.email_id].triage,
                   got=f"flagged, nearest {r.nearest}")
              for r in flagged if labels[r.email_id].triage != "redundant"]
    return Score(_ratio(len(flagged) - len(misses), len(flagged)), misses)


# ---- Suggestions and quotes ----

def linked_emails(s: Suggestion) -> set[str]:
    """Every email a suggestion links to: its sections' emails and its claims' emails."""
    return {sec.email_id for sec in s.sections} | {c.rsplit(".c", 1)[0] for c in s.claim_ids}


def stray_suggestions(suggestions: Iterable[Suggestion], labels: Labels) -> Score:
    """Count of suggestions whose only linked emails the corpus labels redundant, low_value or irrelevant."""
    misses = []
    for s in suggestions:
        linked = sorted(i for i in linked_emails(s) if i in labels)
        if linked and all(labels[i].triage in NOISE_LABELS for i in linked):
            misses.append(Miss(email_id=",".join(linked), measure="stray_suggestions",
                               expected="a signal email", got=f"{s.id}: {','.join(labels[i].triage for i in linked)}"))
    return Score(float(len(misses)), misses)


def quote_faithfulness(notes: Iterable[AttentionNote], suggestions: Iterable[Suggestion],
                       bodies: Mapping[str, str]) -> Score:
    """Share of quoted sections, in notes and suggestions, found verbatim in the email body."""
    sections: list[tuple[str, LinkedSection]] = [(n.email_id, sec) for n in notes for sec in n.sections]
    sections += [(s.id, sec) for s in suggestions for sec in s.sections]
    misses = [Miss(email_id=sec.email_id, measure="quote_faithfulness", expected=f"verbatim quote in {owner}",
                   got=sec.quote[:80])
              for owner, sec in sections if not quote_in(sec.quote, bodies.get(sec.email_id, ""))]
    return Score(_ratio(len(sections) - len(misses), len(sections)), misses)


def meetings_share(triage: Iterable[TriageRecord]) -> Score:
    """Share of emails whose Jev email type is meeting-like (`config.MEETING_LIKE_TYPES`)."""
    records = list(triage)
    return Score(_ratio(sum(1 for t in records if t.email_type in config.MEETING_LIKE_TYPES), len(records)))


def email_type_accuracy(triage: Iterable[TriageRecord], labels: Labels, results: Results) -> Score:
    """Share of emails whose Jev email type (most probable option) equals the corpus `email_type`.

    A quarantined email counts as a miss; an email whose label has no email_type is left out.
    """
    by_id = {t.email_id: t for t in triage}
    ids = [i for i, lab in labels.items() if lab.email_type is not None and i in by_id]
    misses = []
    for i in ids:
        want = labels[i].email_type or ""
        quarantined = (r := results.get(i)) is not None and r.gate == "quarantine"
        got = "quarantined" if quarantined else by_id[i].email_type
        if got != want:
            misses.append(Miss(email_id=i, measure="email_type_accuracy", expected=want, got=got))
    return Score(_ratio(len(ids) - len(misses), len(ids)), misses)


